const $=id=>document.getElementById(id),E=RetailEngine,C=$('store'),ctx=C.getContext('2d');
const W=24,H=15,S=43,OX=84,OY=81,key=(x,y)=>y*W+x,xy=n=>[n%W,Math.floor(n/W)];
const depts=[{name:'Fresh produce',item:'Apples',x:5,y:4,color:'#82a45d',icon:'●'},{name:'Bakery',item:'Bread',x:11,y:4,color:'#cba16a',icon:'▰'},{name:'Dairy',item:'Milk',x:17,y:4,color:'#a0b9bd',icon:'▥'},{name:'Pantry',item:'Pasta',x:5,y:9,color:'#c9a85d',icon:'▥'},{name:'Household',item:'Soap',x:11,y:9,color:'#b5a8c6',icon:'▰'},{name:'Drinks',item:'Juice',x:17,y:9,color:'#c3835b',icon:'▥'}];
const dock=key(2,12),stockroom=key(2,2),pickup=key(21,12),entrance=key(12,13),walls=new Set();
depts.forEach(d=>{d.target=key(d.x+1,d.y+2);for(let x=d.x;x<d.x+3;x++)for(let y=d.y;y<d.y+2;y++)walls.add(key(x,y));});
let state,task='pick',qty=2,blocking=false,last=0,progress=0,visual={x:2,y:12},logs=[];
function reset(){state={pos:dock,battery:100,stock:depts.map(()=>12),reserve:depts.map(()=>30),load:0,completed:0,cost:0,expanded:0,replans:0,time:0,blocked:new Set(),rush:false,paused:false,mission:null,path:[],explored:[],actionTime:0,status:'Ready for a new mission'};visual={x:2,y:12};progress=0;$('pause').textContent='Ⅱ Pause';$('crowd').classList.remove('active-tool');log('Pip checked in at the charging dock.');update();}
function neighbors(n){const [x,y]=xy(n);return [[x,y-1],[x+1,y],[x,y+1],[x-1,y]].filter(([a,b])=>a>=0&&a<W&&b>=1&&b<H-1&&!walls.has(key(a,b))&&!state.blocked.has(key(a,b))).map(([a,b])=>[key(a,b),state.rush&&a>=9&&a<=14?4:1]);}
function route(a,b,method=$('algorithm').value){const [gx,gy]=xy(b);return E.search(a,b,neighbors,n=>{const[x,y]=xy(n);return Math.abs(gx-x)+Math.abs(gy-y);},method);}
function time(){return `${String(9+Math.floor(state.time/60)).padStart(2,'0')}:${String(state.time%60).padStart(2,'0')}`;}
function log(t){logs.unshift(`${time()} · ${t}`);$('journal').textContent=logs[0];$('notice').textContent=t;}
function update(){ $('battery').textContent=Math.floor(state.battery)+'%';$('robotstatus').textContent=state.status;$('clock').textContent=time();$('completed').textContent=String(state.completed).padStart(2,'0');$('cost').innerHTML=state.cost+'<small> units</small>';$('expanded').textContent=state.expanded;$('replans').textContent=state.replans;$('dispatch').disabled=!!state.mission;$('charge').disabled=!!state.mission;$('quantity').textContent=qty;const p=$('product').value;$('stockinfo').textContent=p==='all'?'Quantity of each item':state.stock[+p]+' on shelf';$('maphint').textContent=state.paused?'Simulation paused':state.mission?state.status:'Pip is ready. Choose a mission to get moving.';$('inventory').innerHTML='<table><tr><th>Product</th><th>Shelf</th><th>Stockroom</th></tr>'+depts.map((d,i)=>`<tr><td>${d.item}</td><td>${state.stock[i]}</td><td>${state.reserve[i]}</td></tr>`).join('')+'</table>';}
function plan(replan=false){if(!state.mission)return;const goal=state.mission.stages[0].at,r=route(state.pos,goal);state.path=r.path.slice(1);state.explored=r.explored;state.expanded+=r.explored.length;if(replan)state.replans++;state.status=r.path.length?state.mission.stages[0].label:'Route blocked · clear an aisle';progress=0;update();}
function dispatch(charge=false){if(state.mission)return;const selected=$('product').value,ids=selected==='all'?[0,2,1]:[+selected],stages=[];
 if(charge){stages.push({at:dock,label:'Returning to charging dock',type:'charge'});}else if(task==='inspect'){depts.forEach((d,i)=>stages.push({at:d.target,label:'Inspecting '+d.name,type:'inspect',id:i}));}
 else if(task==='pick'){if(qty*ids.length>8)return log('Payload exceeds Pip’s 8 kg limit. Reduce quantity.');if(ids.some(i=>state.stock[i]<qty))return log('Insufficient shelf stock. Restock before picking.');ids.forEach(i=>stages.push({at:depts[i].target,label:'Collecting '+depts[i].item,type:'pick',id:i}));stages.push({at:pickup,label:'Delivering to the pickup desk',type:'deliver'});}
 else if(task==='restock'){if(ids.length!==1)return log('Choose one department to restock.');if(qty>8)return log('Payload exceeds 8 kg.');if(state.reserve[ids[0]]<qty)return log('Not enough stock in the stockroom.');stages.push({at:stockroom,label:'Collecting stockroom supplies',type:'collect',id:ids[0]},{at:depts[ids[0]].target,label:'Restocking '+depts[ids[0]].name,type:'restock',id:ids[0]});}
 else {if(ids.length!==1)return log('Choose one department for customer guidance.');stages.push({at:entrance,label:'Meeting customer at the entrance',type:'meet'},{at:depts[ids[0]].target,label:'Guiding customer to '+depts[ids[0]].name,type:'assist'});}
 let pos=state.pos,total=0;for(const s of [...stages,...(charge?[]:[{at:dock}])]){const r=route(pos,s.at);if(!r.path.length)return log('Mission unreachable. Clear obstacles first.');total+=r.cost;pos=s.at;}if(state.battery<total*.18+2)return log('Not enough battery for this mission and return. Charge first.');
 state.mission={stages,qty,charge,following:false};state.actionTime=0;log(charge?'Charging mission accepted.':'Mission accepted. Pip is on the way.');plan();}
function act(){const m=state.mission,s=m.stages[0];if(s.type==='charge'){state.battery=Math.min(100,state.battery+4);if(state.battery<100){state.status='Charging · topping up the battery';return;}}if(s.type==='pick'){state.stock[s.id]-=m.qty;state.load+=m.qty;}if(s.type==='collect'){state.reserve[s.id]-=m.qty;state.load+=m.qty;}if(s.type==='restock'){state.stock[s.id]+=m.qty;state.load-=m.qty;}if(s.type==='deliver')state.load=0;if(s.type==='meet')m.following=true;log(s.type==='inspect'?`${depts[s.id].name}: ${state.stock[s.id]} units on shelf.`:s.label+' · done');m.stages.shift();state.actionTime=0;if(!m.stages.length){if(!m.charge)state.completed++;state.status='Mission complete · ready for the next';state.mission=null;state.path=[];log('Mission complete. Nice work, team.');}else plan();update();}
function tick(dt){if(state.paused||!state.mission)return;const speed=+$('speed').value;progress+=dt*speed;if(state.path.length){const next=state.path[0],cost=neighbors(state.pos).find(([n])=>n===next)?.[1];if(cost===undefined){plan(true);return;}if(state.battery<cost*.18){state.status='Low battery · reset to recover';update();return;}const [x,y]=xy(state.pos),[nx,ny]=xy(next),t=Math.min(1,progress/(210*cost));visual={x:x+(nx-x)*t,y:y+(ny-y)*t};if(t===1){state.pos=state.path.shift();state.cost+=cost;state.time+=cost;state.battery=Math.max(0,state.battery-cost*.18);progress=0;update();}}else if(state.pos===state.mission.stages[0].at&&progress>650){state.time++;progress=0;act();}}
function rect(x,y,w,h,c,r=0){ctx.fillStyle=c;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill();}function text(t,x,y,size=12,color='#596d52',weight='500'){ctx.fillStyle=color;ctx.font=`${weight} ${size}px Arial`;ctx.fillText(t,x,y);}function center(n){const[x,y]=xy(n);return [OX+x*S+S/2,OY+y*S+S/2];}
function draw(ts){ctx.clearRect(0,0,C.width,C.height);rect(0,0,1200,760,'#dce3cc');rect(25,24,1150,710,'#b1bca1',20);rect(35,30,1130,685,'#f1efdc',14);rect(35,30,1130,91,'#385e46',14);rect(35,99,1130,22,'#30513b');text('LOCAL GOODS. BETTER DAYS.',817,73,15,'#b9c7a4','600');text('OPEN 09:00 — 21:00',924,96,10,'#8fa784');
 for(let y=1;y<H-1;y++)for(let x=0;x<W;x++){rect(OX+x*S,OY+y*S,S-1,S-1,(x+y)%2?'#efeddc':'#eae9d7');if(state.rush&&x>=9&&x<=14&&!walls.has(key(x,y)))rect(OX+x*S,OY+y*S,S-1,S-1,'#e8d9b0');}
 const zone=(n,label,color)=>{const[x,y]=center(n);rect(x-39,y-28,78,57,color,7);text(label,x-30,y+5,10,'#f7f6e9','700');};zone(stockroom,'STOCKROOM','#a5a581');zone(dock,'ϟ CHARGING','#6e9274');zone(pickup,'PICKUP ↗','#bb9870');
 text('01  FRESH & DAILY',OX+200,167,11,'#8a9776','700');text('02  HOME & PANTRY',OX+200,384,11,'#8a9776','700');
 depts.forEach((d,i)=>{const x=OX+d.x*S,y=OY+d.y*S;rect(x+5,y+9,129,87,'#c2c5ad',7);rect(x,y,129,82,'#777d63',5);rect(x+4,y+3,121,35,'#d7cfad',3);rect(x+4,y+43,121,34,'#d7cfad',3);for(let a=0;a<7;a++)for(let b=0;b<2;b++){const px=x+9+a*16,py=y+8+b*40;if(a+b*7>=state.stock[i])continue;rect(px+1,py+2,11,24,d.color,3);rect(px+3,py+5,7,8,i===2?'#f6f5e6':'#ffffff45',1);if(i===0){ctx.fillStyle=a%2?'#b7bd62':'#a1b157';ctx.beginPath();ctx.arc(px+5,py+11,6,0,Math.PI*2);ctx.fill();}}rect(x+10,y+81,108,22,'#faf8e8',3);text(d.name.toUpperCase(),x+17,y+96,9,'#6d755a','700');text(String(i+1).padStart(2,'0'),x-21,y+44,12,'#9ba388');});
 // Checkout counters and decorative market details.
 for(let i=0;i<3;i++){let x=OX+20*S,y=OY+(3+i*2.5)*S;rect(x+4,y+5,88,63,'#c8c9ae',8);rect(x,y,85,59,'#b6bca0',7);rect(x+7,y+7,43,45,'#667866',5);rect(x+55,y+10,23,20,'#3e5b4b',3);rect(x+58,y+12,17,12,'#b2d1b0',2);text('CHECKOUT '+(i+1),x-2,y+75,8,'#869275');}
 text('↓  ENTRANCE',OX+10*S,OY+14*S,13,'#859273','600');for(let i=0;i<3;i++){const x=60,y=220+i*65;rect(x,y,42,43,'#c7b998',4);for(let a=0;a<3;a++)for(let b=0;b<3;b++){ctx.fillStyle=(a+b)%2?'#92a15e':'#c7a85c';ctx.beginPath();ctx.arc(x+9+a*11,y+9+b*12,5,0,7);ctx.fill();}}
 if($('overlay').checked){state.explored.forEach(n=>{if(walls.has(n))return;const[x,y]=center(n);rect(x-3,y-3,6,6,'#759e8040',2);});if(state.path.length){ctx.strokeStyle='#469a7c';ctx.lineWidth=4;ctx.setLineDash([5,8]);ctx.beginPath();let[x,y]=center(state.pos);ctx.moveTo(x,y);state.path.forEach(n=>{[x,y]=center(n);ctx.lineTo(x,y);});ctx.stroke();ctx.setLineDash([]);const[xg,yg]=center(state.mission.stages[0].at);ctx.strokeStyle='#4e9271';ctx.lineWidth=2;ctx.beginPath();ctx.arc(xg,yg,17,0,7);ctx.stroke();}}
 state.blocked.forEach(n=>{const[x,y]=center(n);rect(x-16,y-13,32,26,'#c67f5c',4);text('×',x-8,y+8,26,'#ffebc7');});
 function shopper(x,y,color){ctx.fillStyle='#293e3220';ctx.beginPath();ctx.ellipse(x,y+14,13,6,0,0,7);ctx.fill();rect(x-8,y-3,16,20,color,6);ctx.fillStyle='#d6b397';ctx.beginPath();ctx.arc(x,y-8,7,0,7);ctx.fill();rect(x+12,y+4,13,14,'#c0c1a7',2);}
 shopper(OX+3.5*S,OY+7.5*S,'#b68c6c');shopper(OX+19*S,OY+6.4*S,'#8b9fa6');if(state.mission?.following)shopper(OX+visual.x*S+S/2-25,OY+visual.y*S+S/2+13,'#bd9d68');else shopper(OX+12*S+S/2,OY+13*S+S/2,'#bd9d68');
 const rx=OX+visual.x*S+S/2,ry=OY+visual.y*S+S/2;ctx.fillStyle='#294a3730';ctx.beginPath();ctx.ellipse(rx,ry+20,23,10,0,0,7);ctx.fill();rect(rx-23,ry-9,7,24,'#415d48',4);rect(rx+16,ry-9,7,24,'#415d48',4);rect(rx-19,ry-20,38,38,'#cbd5b5',11);rect(rx-18,ry-24,36,34,'#fbfae8',11);rect(rx-13,ry-15,26,15,'#2e5c4c',6);rect(rx-8,ry-11,4,5,'#bfdf9f',2);rect(rx+4,ry-11,4,5,'#bfdf9f',2);rect(rx-5,ry+4,10,3,'#96b279',2);if(state.load){rect(rx-13,ry+17,26,17,'#bb9b68',3);text(state.load+'',rx-4,ry+29,10,'#fff9e8','700');}text('PIP',rx-10,ry-31,10,'#35694e','700');
 // Potted plants soften the edges of the floor.
 [104,1092].forEach(x=>{rect(x-9,667,24,19,'#b49b75',4);for(let a=0;a<5;a++){ctx.fillStyle=a%2?'#6c8b58':'#8fa16a';ctx.beginPath();ctx.ellipse(x+2+Math.cos(a*2)*8,660+Math.sin(a*2)*9,7,12,a,0,7);ctx.fill();}});
}
function frame(t){tick(Math.min(t-last,100));last=t;draw(t);requestAnimationFrame(frame);}
document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>{document.querySelectorAll('.nav').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('.view').forEach(v=>v.classList.toggle('hidden',v.id!==b.dataset.view));update();});
document.querySelectorAll('.task').forEach(b=>b.onclick=()=>{task=b.dataset.task;document.querySelectorAll('.task').forEach(x=>x.classList.toggle('selected',x===b));$('product-fields').classList.toggle('hidden',task==='inspect');});
$('plus').onclick=()=>{qty=Math.min(8,qty+1);update();};$('minus').onclick=()=>{qty=Math.max(1,qty-1);update();};$('product').onchange=update;$('dispatch').onclick=()=>dispatch();$('charge').onclick=()=>dispatch(true);$('pause').onclick=()=>{state.paused=!state.paused;$('pause').textContent=state.paused?'▶ Resume':'Ⅱ Pause';update();};$('reset').onclick=reset;
$('algorithm').onchange=()=>{const notes={'A*':'Balances travel cost with distance to the goal.',UCS:'Finds the least-cost path without a heuristic.',BFS:'Finds the fewest moves, ignoring aisle costs.',DFS:'Explores deeply; routes may be much longer.',Greedy:'Follows estimated distance; may miss cheaper routes.'};$('algonote').textContent=notes[$('algorithm').value];if(state.mission)plan(true);};
$('block').onclick=()=>{blocking=!blocking;$('block').classList.toggle('active-tool',blocking);log(blocking?'Click an empty aisle to add or remove an obstacle.':'Obstacle placement off.');};
C.onclick=e=>{if(!blocking)return;const b=C.getBoundingClientRect(),x=Math.floor(((e.clientX-b.left)*1200/b.width-OX)/S),y=Math.floor(((e.clientY-b.top)*760/b.height-OY)/S),n=key(x,y);if(x<0||x>=W||y<1||y>=H-1||walls.has(n)||n===state.pos||[dock,stockroom,pickup,entrance,...depts.map(d=>d.target)].includes(n))return log('Keep robot, service stations and shelves clear.');if(state.blocked.has(n))state.blocked.delete(n);else state.blocked.add(n);log('Floor updated. Checking the current route.');if(state.mission)plan(true);};
$('crowd').onclick=()=>{state.rush=!state.rush;$('crowd').classList.toggle('active-tool',state.rush);log(state.rush?'Rush hour: central aisle travel cost is now 4.':'Rush hour cleared. Aisle costs restored to 1.');if(state.mission)plan(true);};
function resultsTable(rows){return '<table><tr><th>Search</th><th>Cost</th><th>Expanded</th><th>ms</th></tr>'+rows.map(([a,r])=>`<tr><td>${a}</td><td>${Number.isFinite(r.cost)?r.cost:'No path'}</td><td>${r.explored.length}</td><td>${r.ms.toFixed(2)}</td></tr>`).join('')+'</table>';}
$('compare').onclick=()=>{$('comparison').innerHTML=resultsTable(['BFS','DFS','UCS','Greedy','A*'].map(a=>[a,route(state.pos,depts[$('product').value==='all'?0:+$('product').value].target,a)]));};
$('reference').onclick=()=>{const graph={S:[['A',4],['B',3]],A:[['C',4],['D',7]],B:[['D',4],['E',6]],C:[['D',2],['G',5]],D:[['E',2],['G',3]],E:[['G',4]],G:[]},h={S:8,A:7,B:6,C:4,D:3,E:4,G:0};$('reference-result').innerHTML=resultsTable(['BFS','DFS','UCS','Greedy','A*'].map(a=>[a,E.search('S','G',n=>graph[n],n=>h[n],a)]))+'<p>Fixed FA1 graph, S → G. Costs are illustrative travel minutes.</p>';};
$('schedule').onclick=()=>{const r=E.schedule([{id:'R1',capacity:8,battery:100},{id:'R2',capacity:5,battery:90},{id:'R3',capacity:7,battery:80}].filter(x=>!$('breakdown').checked||x.id!=='R1'),[{name:'Restock 7 kg',load:7},{name:'Pick 4 kg',load:4},{name:'Deliver 4 kg',load:4}]);$('schedule-result').innerHTML='<strong>'+(r.ok?'Feasible allocation':'No feasible allocation — reschedule or add a robot')+'</strong><pre>'+r.log.join('\n')+'</pre><p>Delivery slot check: 08:10 + 12 min misses 08:20 handoff. Backtrack to 08:05; completion 08:17 leaves 3 min staging.</p>';};
$('strategy').onclick=()=>{const o=[{name:'Add checkout staff',scores:[75,65]},{name:'Reroute robots',scores:[50,70]},{name:'Keep current plan',scores:[20,60]}].filter(x=>$('staff').checked||x.name!=='Add checkout staff'),a=E.minimax(o),b=E.minimax(o,true);$('strategy-result').innerHTML='<strong>'+b.best+' · worst-case utility '+b.value+'</strong><pre>'+o.map(x=>x.name+': '+x.scores.join(' / ')).join('\n')+'</pre><p>Minimax: '+a.count+' leaves. Alpha-Beta: '+b.count+' leaves, '+b.skipped+' pruned. Same decision.</p><p>Illustrative utility scores from FA1; this workbench does not dispatch staff or robots.</p>';};
reset();requestAnimationFrame(frame);

